    @foreach($groups as $group => $permissions)<fieldset class="rounded-xl border p-4 sm:p-5" x-data><legend class="px-2 text-sm font-semibold">{{ $group }}</legend><label class="mb-3 flex items-center gap-2 text-sm font-medium text-[var(--accent)]"><input class="size-4 accent-[var(--accent)]" type="checkbox" @change="const boxes=[...$el.closest('fieldset').querySelectorAll('input[name=\'permissions[]\']')]; boxes.forEach(box => { if (box.checked !== $el.checked) { box.checked=$el.checked; box.dispatchEvent(new Event('change')); } })"> Select all in {{ $group }}</label><div class="grid gap-2 md:grid-cols-2">@foreach($permissions as $permission)<label class="flex gap-3 rounded-xl p-3 transition hover:bg-[var(--interactive)]"><input class="mt-0.5 size-4 accent-[var(--accent)]" type="checkbox" name="permissions[]" value="{{ $permission->id }}" @change="selected += $el.checked ? 1 : -1" {{ $selected->contains($permission->id) ? 'checked' : '' }}><span><b class="block text-sm font-medium">{{ $permission->name }}</b><small class="mt-0.5 block leading-5 text-[var(--text-muted)]">{{ $permission->description }}</small></span></label>@endforeach</div></fieldset>@endforeach
